#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

struct Fenwick {
    int n;
    vector<int> bit;

    Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int idx, int val) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += val;
    }

    int sum(int idx) {
        int res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    ll X1, X2;
    cin >> N >> X1 >> X2;

    vector<pair<ll, ll>> lines(N);
    vector<ll> vals;
    vals.reserve(N);

    for (int i = 0; i < N; ++i) {
        ll A, B;
        cin >> A >> B;
        ll L = A * X1 + B;
        ll R = A * X2 + B;
        lines[i] = {L, R};
        vals.push_back(R);
    }

    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    sort(lines.begin(), lines.end(), [](const auto& a, const auto& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    Fenwick fw((int)vals.size());
    ll ans = 0;

    int i = 0;
    while (i < N) {
        int j = i;
        while (j < N && lines[j].first == lines[i].first) ++j;

        int k = j - i;
        ans += 1LL * k * (k - 1) / 2;

        for (int t = i; t < j; ++t) {
            ll R = lines[t].second;
            int idx = lower_bound(vals.begin(), vals.end(), R) - vals.begin() + 1;
            int less = fw.sum(idx - 1);
            ans += i - less;
        }

        for (int t = i; t < j; ++t) {
            ll R = lines[t].second;
            int idx = lower_bound(vals.begin(), vals.end(), R) - vals.begin() + 1;
            fw.add(idx, 1);
        }

        i = j;
    }

    cout << ans << '\n';
    return 0;
}
